metrics.workdir_dsl:
workspace "Bookshop" "A simple online bookshop" {

    model {
        customer = person "Customer" "A customer who browses the catalogue and buys books"

        bookshop = softwareSystem "Bookshop" "An online bookshop where customers can browse books and place orders" {
            webStore = container "Web Store" "The web application customers use to browse the catalogue and place orders" "Java / Spring Boot"
            orderProcessor = container "Order Processor" "Processes and fulfils customer orders" "Python"
        }

        customer -> webStore "browses the catalogue and places orders through" "HTTPS"
        webStore -> orderProcessor "submits new orders to" "gRPC"
    }

    views {
        systemContext bookshop "bookshopContext" "System context for the Bookshop" {
            include *
            autoLayout
        }
    }
}
